const T=(ru,kk,en)=>({ru,kk,en});
export const migrationQuiz=[
 {id:'q1',topic:T('Уведомление о прибытии','Келу туралы хабарлама','Arrival notification'),question:T('Вы заселились в квартиру после въезда. Кто уведомляет органы внутренних дел и какой срок указан в пункте 17 Правил №148?','Елге кірген соң пәтерге қоныстандыңыз. №148 қағидалардың 17-тармағы бойынша ішкі істер органдарын кім және қай мерзімде хабардар етеді?','You have moved into an apartment after entering the country. Who notifies internal affairs bodies, and what period does paragraph 17 of Rules No.148 specify?'),options:[T('Принимающая сторона — в течение трёх рабочих дней со дня прибытия','Қабылдаушы тарап — келген күннен бастап үш жұмыс күні ішінде','The receiving party, within three working days from arrival'),T('Иностранец — после получения ИИН','Шетелдік — ЖСН алғаннан кейін','The foreign citizen, after obtaining an IIN'),T('Банк — в течение трёх календарных дней после открытия счёта','Банк — шот ашқаннан кейін үш күнтізбелік күн ішінде','The bank, within three calendar days after opening an account')],correct:0,explanation:T('Обязанность по уведомлению возложена на принимающее лицо. Попросите подтверждение подачи. Три рабочих дня нельзя заменять тремя календарными; конкретную крайнюю дату с учётом календаря здесь не рассчитываем.','Хабарлау міндеті қабылдаушы тұлғаға жүктелген. Өтінімнің растауын сұраңыз. Үш жұмыс күні үш күнтізбелік күнге тең емес; бұл жерде күнтізбе бойынша нақты соңғы күн есептелмейді.','The receiving party is responsible for notification. Ask for submission confirmation. Three working days are not three calendar days; this question does not calculate the exact calendar deadline.'),sourceIds:['entry']},
 {id:'q8',topic:T('РВП для учёбы','Оқу үшін уақытша тұру','Student temporary residence'),question:T('Вы зачислены в вуз и готовите РВП для учёбы. Какова роль университета?','ЖОО-ға қабылданып, оқу үшін уақытша тұру рұқсатын дайындайсыз. Университеттің рөлі қандай?','You have enrolled at a university and are preparing temporary residence permission for study. What is the university’s role?'),options:[T('Заменить все документы студенческим билетом','Барлық құжатты студенттік билетпен алмастыру','Replace the whole application with a student card'),T('Как принимающая организация подготовить ходатайство и подать заявление с комплектом по учебному основанию','Қабылдаушы ұйым ретінде өтінішхат дайындап, оқу негізіндегі құжаттармен өтініш беру','As the receiving organisation, prepare its petition and submit the application with the study-basis documents'),T('Оформить только банковский счёт студента','Тек студенттің банк шотын ашу','Only open the student’s bank account')],correct:1,explanation:T('Для учебного основания в официальном перечне есть ходатайство организации образования. Заявление РВП подаёт принимающая сторона; студент готовит свои документы. Сохраните результат услуги и проверьте цель, адрес и срок.','Оқу негізіне арналған ресми тізімде білім беру ұйымының өтінішхаты бар. Уақытша тұру өтінішін қабылдаушы тарап береді; студент өз құжаттарын дайындайды. Қызмет нәтижесін сақтап, мақсатын, мекенжайын және мерзімін тексеріңіз.','The official study-basis list includes a petition from the educational organisation. The receiving party submits the temporary residence application; the student prepares their own documents. Keep the service result and check its purpose, address and dates.'),sourceIds:['rvp-apply']},
 {id:'q3',topic:T('Получение ИИН','ЖСН алу','Obtaining an IIN'),question:T('В паспорте ФИО и место рождения написаны латиницей. Нужен ли перевод только ради получения ИИН?','Паспорттағы аты-жөні мен туған жері латын әріптерімен жазылған. Тек ЖСН алу үшін аударма қажет пе?','Your passport gives your name and place of birth in Latin letters. Is a translation required solely to obtain an IIN?'),options:[T('Перевод обязателен для любого иностранного паспорта','Кез келген шетел паспортына аударма міндетті','A translation is required for every foreign passport'),T('По карточке услуги перевод нужен, если установочных данных нет ни на кириллице, ни на латинице','Қызмет карточкасы бойынша жеке деректер кирилл не латын әріптерімен берілмесе, аударма қажет','The service requires a translation if identity details are in neither Cyrillic nor Latin letters'),T('Перевод заменяет действительный паспорт','Аударма жарамды паспортты алмастырады','A translation replaces a valid passport')],correct:1,explanation:T('Услуга ИИН требует заявление и действительный документ личности. Нотариальный перевод добавляется при отсутствии установочных данных на кириллице или латинице. Не переносите это условие на другие миграционные услуги: у них отдельные перечни.','ЖСН қызметіне өтініш пен жарамды жеке бас құжаты қажет. Жеке деректер кирилл не латын әріптерімен болмаса, нотариалды аударма қосылады. Басқа көші-қон қызметтерінің талаптары бөлек.','The IIN service requires an application and valid identity document. A notarised translation is added when identity details are in neither Cyrillic nor Latin letters. Other migration services have separate requirements.'),sourceIds:['faq-iin-service']},
 {id:'q4',topic:T('Счёт без ВНЖ','Ықтиярхатсыз шот','Account without a residence card'),question:T('Вы впервые открываете счёт в Halyk по иностранному паспорту, ВНЖ нет. Как подготовиться по памятке банка?','Ықтиярхатсыз шетел паспортымен Halyk-те алғаш рет шот ашасыз. Банк жадынамасы бойынша қалай дайындаласыз?','You are opening your first Halyk account with a foreign passport and no Kazakhstan residence card. What does its guidance require?'),options:[T('Идти в отделение с паспортом, ИИН, подтверждениями основания нахождения и адреса; заполнить анкету банка','Паспорт, ЖСН, елде болу негізі мен мекенжай растауын алып бөлімшеге барып, банк сауалнамасын толтыру','Visit a branch with your passport, IIN, evidence of your basis for staying and address, and complete the bank form'),T('Оформить всё онлайн: иностранного паспорта достаточно','Барлығын онлайн ресімдеу: шетел паспорты жеткілікті','Complete everything online using only the foreign passport'),T('Принести только договор аренды без паспорта','Паспортсыз тек жалдау шартын апару','Bring only a lease, without a passport')],correct:0,explanation:T('Это опубликованные требования конкретного банка к первичному обращению иностранца без ВНЖ. Перед визитом проверьте текущую памятку Halyk; открытие не гарантировано, а другие банки могут запросить иной комплект.','Бұл — ықтиярхаты жоқ шетелдіктің алғашқы өтінішіне осы банктің жариялаған талаптары. Барар алдында Halyk-тің өзекті жадынамасын тексеріңіз; шот ашылуына кепілдік жоқ, басқа банктердің тізімі өзгеше болуы мүмкін.','These are this bank’s published requirements for a first application without a residence card. Recheck Halyk’s current guidance before visiting; approval is not guaranteed and other banks may request different documents.'),sourceIds:['faq-halyk-nonresident']},
 {id:'q7',topic:T('Работа граждан ЕАЭС','ЕАЭО азаматтарының жұмысы','EAEU citizens at work'),question:T('Гражданин Кыргызстана устраивается по трудовому договору в Казахстане. Нужно ли ему отдельное разрешение на работу только из-за иностранного гражданства?','Қырғызстан азаматы Қазақстанда еңбек шартымен жұмысқа орналасады. Тек шетел азаматы болғандықтан бөлек жұмыс рұқсаты қажет пе?','A Kyrgyzstan citizen takes a job under an employment contract in Kazakhstan. Is a separate work permit required solely because they are foreign?'),options:[T('Да, одинаковое разрешение требуется всем иностранцам','Иә, барлық шетелдікке бірдей рұқсат қажет','Yes, the same permit is required for every foreign citizen'),T('Нет, для граждан ЕАЭС действует освобождение; договор и основание проживания оформляются отдельно','Жоқ, ЕАЭО азаматтары босатылған; шарт пен тұру негізі бөлек ресімделеді','No, EAEU citizens are exempt; the contract and residence basis still need separate attention'),T('Нет, поэтому трудовой договор тоже не нужен','Жоқ, сондықтан еңбек шарты да қажет емес','No, so an employment contract is unnecessary too')],correct:1,explanation:T('Разрешение не требуется гражданам России, Беларуси, Армении и Кыргызстана в рамках ЕАЭС. Это не освобождение от трудового договора и миграционных процедур. Правило нельзя переносить на все страны СНГ.','ЕАЭО аясында Ресей, Беларусь, Армения және Қырғызстан азаматтарына жұмыс рұқсаты қажет емес. Бұл еңбек шарты мен көші-қон рәсімдерінен босатпайды. Ережені барлық ТМД елдеріне қолдануға болмайды.','Within the EAEU, citizens of Russia, Belarus, Armenia and Kyrgyzstan do not need a work permit. Employment contracts and migration procedures still apply. This rule does not extend to every CIS country.'),sourceIds:['faq-eaeu-work','labour']},
 {id:'q5',topic:T('ПМЖ и ВНЖ','Тұрақты тұру және ықтиярхат','Permanent residence and residence card'),question:T('После въезда вам обещают сразу оформить ВНЖ без проверки оснований. Какой шаг обоснован?','Кіргеннен кейін негіздерді тексермей бірден ықтиярхат беруді уәде етті. Қандай қадам дұрыс?','After arrival, someone promises an immediate residence card without checking eligibility. What should you do?'),options:[T('Сначала проверить основания и процедуру разрешения на постоянное проживание','Алдымен тұрақты тұру рұқсатының негіздері мен рәсімін тексеру','First verify eligibility and the permanent-residence permission procedure'),T('Считать покупку билета основанием ПМЖ','Билет сатып алуды тұрақты тұру негізі деп санау','Treat buying a ticket as permanent-residence eligibility'),T('Заменить все проверки договором аренды','Барлық тексеруді жалдау шартымен алмастыру','Replace all checks with a rental agreement')],correct:0,explanation:T('Разрешение на постоянное проживание и оформление карточки ВНЖ — последовательные этапы. Основания, применимость критериальной оценки и документы нужно уточнять по официальной процедуре.','Тұрақты тұру рұқсаты мен ықтиярхат беру — кезекті кезеңдер. Негіздер, критериалды бағалау және құжаттар ресми рәсім бойынша нақтыланады.','Permanent-residence permission precedes the residence card. Check eligibility, applicability of assessment and documents through the official procedure.'),sourceIds:['pmz-overview','pmz-apply']},
 {id:'q6',topic:T('Замена ВНЖ','Ықтиярхатты ауыстыру','Residence-card replacement'),question:T('Карточка ВНЖ скоро заканчивается. Как различить нужные действия?','Ықтиярхаттың мерзімі аяқталуға жақын. Қажетті әрекеттерді қалай ажыратасыз?','Your residence card is about to expire. How do you identify the required procedure?'),options:[T('Игнорировать дату: карточка всегда бессрочная','Күнді елемеу: карточка әрқашан мерзімсіз','Ignore the date because a residence card never expires'),T('Уточнить замену карточки и отдельно проверить сохранение основания постоянного проживания','Карточканы ауыстыруды нақтылап, тұрақты тұру негізінің сақталуын бөлек тексеру','Check card replacement and separately confirm that permanent-residence grounds remain valid'),T('Повторить только въездное уведомление вместо замены','Ауыстыру орнына тек келу хабарламасын қайталау','Repeat the arrival notification instead of replacing the card')],correct:1,explanation:T('Замена документа при истечении срока отличается от первичного получения разрешения ПМЖ. Точный порядок и комплект проверяют по услуге; дата в калькуляторе сама по себе не продлевает статус.','Мерзімі біткен құжатты ауыстыру тұрақты тұру рұқсатын алғаш алудан ерекшеленеді. Рәсім мен құжаттар қызмет бойынша тексеріледі; калькулятор мәртебені ұзартпайды.','Replacing an expiring card differs from initially obtaining permanent-residence permission. Check the service requirements; the date tool does not extend status.'),sourceIds:['vnz-card','vnz-replacement']},
 {
  "id": "q11",
  "topic": {
    "ru": "Ходатайство о статусе беженца",
    "kk": "Босқын мәртебесі туралы өтініш",
    "en": "Refugee-status petition"
  },
  "question": {
    "ru": "Вы находитесь в Казахстане и сегодня узнали об обстоятельствах, создающих обоснованные опасения преследования на родине. Когда официальная инструкция требует обратиться за статусом беженца?",
    "kk": "Қазақстанда жүріп, бүгін отаныңызда қудалану қаупін негіздейтін мән-жайлар туралы білдіңіз. Ресми нұсқаулық босқын мәртебесін сұрау үшін қашан жүгінуді талап етеді?",
    "en": "While in Kazakhstan, today you learn of circumstances creating a well-founded fear of persecution at home. When does the official guidance require you to apply for refugee status?"
  },
  "options": [
    {
      "ru": "Только после окончания РВП",
      "kk": "Тек уақытша тұру рұқсаты аяқталған соң",
      "en": "Only after temporary residence permission expires"
    },
    {
      "ru": "В течение пяти рабочих дней с получения ИИН",
      "kk": "ЖСН алғаннан кейін бес жұмыс күні ішінде",
      "en": "Within five working days after obtaining an IIN"
    },
    {
      "ru": "В течение пяти календарных дней со дня, когда стало известно об этих обстоятельствах",
      "kk": "Осы мән-жайлар белгілі болған күннен бастап бес күнтізбелік күн ішінде",
      "en": "Within five calendar days of learning about those circumstances"
    }
  ],
  "correct": 2,
  "explanation": {
    "ru": "Для этого случая инструкция указывает пять календарных дней с момента, когда находящийся в РК человек узнал об обстоятельствах опасения преследования. При обращении после прибытия применяется отдельная формулировка: пять календарных дней со дня прибытия. Ходатайство принимают местные исполнительные органы по вопросам занятости; политическое убежище — другая процедура.",
    "kk": "Бұл жағдай үшін нұсқаулық Қазақстандағы адам қудалану қаупін тудыратын мән-жайлар туралы білген күннен бастап бес күнтізбелік күнді көрсетеді. Келгеннен кейінгі жүгінуге басқа тұжырым қолданылады: келген күннен бастап бес күнтізбелік күн. Өтінішті жұмыспен қамту жөніндегі жергілікті атқарушы орган қабылдайды; саяси баспана — бөлек рәсім.",
    "en": "For this case, the guidance specifies five calendar days from learning about the circumstances while in Kazakhstan. An application following arrival has a separate trigger: five calendar days from arrival. The local executive authority responsible for employment accepts the petition; political asylum is a different procedure."
  },
  "sourceIds": [
    "refugee-apply"
  ]
},
 {id:'q12',topic:T('Приобретение гражданства','Азаматтық алу','Acquiring citizenship'),question:T('Вы гражданин страны СНГ и хотите гражданство Казахстана. Что нужно уточнить сначала?','ТМД елінің азаматы ретінде Қазақстан азаматтығын алғыңыз келеді. Алдымен нені нақтылайсыз?','As a citizen of a CIS country, you want Kazakhstan citizenship. What should you clarify first?'),options:[T('Считать гражданство страны СНГ достаточным для автоматического приёма','ТМД азаматтығын автоматты қабылдауға жеткілікті деп санау','Assume CIS citizenship guarantees automatic admission'),T('Применимые основания общего или упрощённого порядка и документы о прежнем гражданстве','Жалпы не жеңілдетілген тәртіптің негіздері мен бұрынғы азаматтық құжаттарын','Eligibility for the general or simplified procedure and documents concerning prior citizenship'),T('Считать получение ИИН сменой гражданства','ЖСН алуды азаматтық ауыстыру деп санау','Treat obtaining an IIN as changing citizenship')],correct:1,explanation:T('Порядок зависит от законных оснований и применимых договоров. Упрощённый порядок не является автоматическим для всех граждан СНГ; вопросы прежнего гражданства проверяются отдельно.','Тәртіп заңды негіздер мен қолданылатын шарттарға байланысты. Жеңілдетілген тәртіп барлық ТМД азаматтарына автоматты қолданылмайды; бұрынғы азаматтық бөлек тексеріледі.','The procedure depends on legal grounds and applicable treaties. Simplified admission is not automatic for every CIS citizen; prior citizenship must be addressed separately.'),sourceIds:['citizenship-overview','citizenship-simplified']}
];
